def LN(u,g,b):
    mu=u.mean(1,keepdims=True); sd=np.sqrt(u.var(1,keepdims=True)+1e-12); return (u-mu)/sd*g+b
def rel(a,b): return np.linalg.norm(a-b)/np.linalg.norm(b-b.mean(0))
sid=np.repeat(np.arange(64)[:,None],63,1)[msk20]
def greedy(Ac, Fc, m, lam=1.0):
    # forward selection maximizing explained var of Fc by columns of Ac (ridge-ish via lam on diag)
    G=Ac.T@Ac; C=Ac.T@Fc; n=G.shape[0]
    R=G.copy(); Cr=C.copy(); d=np.diag(R).copy()+lam; sel=[]; avail=np.ones(n,bool)
    for it in range(m):
        gain=(Cr**2).sum(1)/np.maximum(d,1e-9); gain[~avail]=-1
        j=int(np.argmax(gain)); sel.append(j); avail[j]=False
        r=R[:,j].copy(); dj=d[j]
        Cr-=np.outer(r/dj, Cr[j]); R-=np.outer(r, r)/dj; d=np.diag(R).copy()+lam
    return np.sort(np.array(sel))
